begin;
do $$
declare a uuid:='ea000000-0000-4000-8000-000000000001'; b uuid:='eb000000-0000-4000-8000-000000000002';
 p uuid; test_comment uuid; result jsonb; avatar jsonb:='{"version":1,"hair":"long04","eyes":"variant01","mouth":"happy01","clothing":"variant01","glasses":"none","hat":"none","beard":"none","accessories":"none","skinColor":"8d5524","hairColor":"3b2418","clothingColor":"0a47d5","backgroundColor":"f6bad8"}';
begin
 insert into auth.users(id,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values
 (a,'portrait-test-a@example.invalid',now(),'{}','{}',now(),now()),(b,'portrait-test-b@example.invalid',now(),'{}','{}',now(),now());
 insert into public.feedback_members(user_id,display_name,starter_credits) values(a,'Portrait A',3),(b,'Portrait B',3);
 perform set_config('request.jwt.claim.sub',a::text,true);
 result:=public.member_profile_save('Portrait A',avatar);
 if result->'avatar'<>avatar then raise exception 'TEST FAILED: saved portrait missing from profile'; end if;
 if (select m.avatar from public.feedback_members m where m.user_id=b) is not null then raise exception 'TEST FAILED: saving changed another member'; end if;
 if public.member_avatar_valid('{}') or public.member_avatar_valid('[]') or public.member_avatar_valid('null') or public.member_avatar_valid(avatar||'{"src":"https://bad.example/a.svg"}') or public.member_avatar_valid(avatar||'{"hair":"long99"}') then raise exception 'TEST FAILED: unsafe avatar accepted'; end if;
 begin perform public.member_profile_save('Portrait A',avatar||'{"src":"<svg onload=alert(1)>"}'); raise exception 'TEST FAILED: unsafe avatar saved'; exception when others then if sqlerrm<>'member_invalid_avatar' then raise; end if; end;
 p:=public.feedback_submit('Portrait test app','https://portrait-test.vercel.app','Web app','People testing a shared member portrait.','Find the profile picture next to the builder name.','Is the profile picture consistent?');
 if not exists(select 1 from jsonb_array_elements(public.feedback_board()->'projects') entry where entry->>'id'=p::text and entry->'avatar'=avatar) then raise exception 'TEST FAILED: project has no saved portrait'; end if;
 test_comment:=public.learn_comment('avatar-test-article','Portrait test article','portrait-test-article','A comment with a portrait, published immediately.');
 result:=public.learn_discussion('avatar-test-article');
 if not exists(select 1 from jsonb_array_elements(result) entry where entry->>'id'=test_comment::text and entry->'avatar'=avatar and entry->>'author_name'='Portrait A') then raise exception 'TEST FAILED: comment did not publish with avatar'; end if;
 if result::text like '%example.invalid%' then raise exception 'TEST FAILED: public comments expose email'; end if;
 avatar:=avatar||'{"hair":"short01"}';
 perform public.member_profile_save('Updated portrait A',avatar);
 if not exists(select 1 from jsonb_array_elements(public.learn_discussion('avatar-test-article')) entry where entry->'avatar'=avatar and entry->>'author_name'='Updated portrait A') then raise exception 'TEST FAILED: old comments did not update'; end if;
 if not exists(select 1 from jsonb_array_elements(public.feedback_board()->'projects') entry where entry->>'id'=p::text and entry->'avatar'=avatar) then raise exception 'TEST FAILED: old projects did not update'; end if;
 perform public.learn_comment('avatar-test-article','Portrait test article','portrait-test-article','Second test comment.');
 perform public.learn_comment('avatar-test-article','Portrait test article','portrait-test-article','Third test comment.');
 begin perform public.learn_comment('avatar-test-other','Other article','other-article','Fourth test comment.'); raise exception 'TEST FAILED: rate limit bypassed across articles'; exception when others then if sqlerrm<>'learn_comment_limit' then raise; end if; end;
 begin perform public.learn_moderate(test_comment,'hide'); raise exception 'TEST FAILED: member removed a comment'; exception when others then if sqlerrm<>'feedback_admin_only' then raise; end if; end;
 begin perform public.learn_moderation(); raise exception 'TEST FAILED: member read reports'; exception when others then if sqlerrm<>'feedback_admin_only' then raise; end if; end;
 perform set_config('request.jwt.claim.sub',b::text,true);
 perform public.learn_report(test_comment,'Spam','A report to test moderation without auto-hiding.');
 perform public.learn_report(test_comment,'Spam','A duplicate report must not count twice.');
 if (select count(*) from public.learn_comment_reports where comment_id=test_comment)<>1 then raise exception 'TEST FAILED: duplicate report added'; end if;
 if jsonb_array_length(public.learn_discussion('avatar-test-article'))<>3 then raise exception 'TEST FAILED: report auto-hid content'; end if;
 insert into public.feedback_admins(user_id) values(b);
 result:=public.learn_moderation();
 if jsonb_array_length(result->'reports')<>1 or result->'reports'->0->>'body'<>'A comment with a portrait, published immediately.' then raise exception 'TEST FAILED: report context missing'; end if;
 perform public.learn_moderate(test_comment,'hide');
 if jsonb_array_length(public.learn_discussion('avatar-test-article'))<>2 then raise exception 'TEST FAILED: takedown failed'; end if;
 if jsonb_array_length(public.learn_moderation()->'reports')<>0 then raise exception 'TEST FAILED: takedown did not resolve report'; end if;
 perform public.learn_moderate(test_comment,'restore');
 if jsonb_array_length(public.learn_discussion('avatar-test-article'))<>3 then raise exception 'TEST FAILED: restoration failed'; end if;
 update public.feedback_members set blocked=true where user_id=a;
 perform set_config('request.jwt.claim.sub',a::text,true);
 begin perform public.member_profile_save('Blocked',avatar); raise exception 'TEST FAILED: blocked member edited profile'; exception when others then if sqlerrm<>'feedback_blocked' then raise; end if; end;
 perform set_config('request.jwt.claim.sub','',true);
 begin perform public.member_profile_save('Anonymous',avatar); raise exception 'TEST FAILED: anonymous profile save'; exception when others then if sqlerrm<>'feedback_sign_in' then raise; end if; end;
 if has_table_privilege('authenticated','public.learn_comments','INSERT') or has_table_privilege('anon','public.learn_comment_reports','SELECT') then raise exception 'TEST FAILED: direct table access'; end if;
 if has_function_privilege('anon','public.member_profile_save(text,jsonb)','EXECUTE') or has_function_privilege('anon','public.learn_moderation()','EXECUTE') then raise exception 'TEST FAILED: anonymous mutation or moderation access'; end if;
end $$;
select 'PASS: profile ownership, safe portrait choices, persistent author pictures, immediate comments, limits, private reports, removal/restore, and RLS' as portrait_checks;
rollback;
